function lift(c, th, dx, dy) {
  const co = Math.cos(th), s = Math.sin(th);
  const tx = c[0] + dx - (co * c[0] - s * c[1]);
  const ty = c[1] + dy - (s * c[0] + co * c[1]);
  return [co, 0, -s, 0, 0, 1, 0, 0, s, 0, co, 0, tx / 1000, 0, -ty / 1000, 1];
}
